    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "SMS codes must be submitted after 5 minutes to verify rejection, and before 5 minutes to verify acceptance."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
