{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik olarak sonlandırılıp sonlandırılmadığı, sistem çalıştırılarak ve süreler beklenerek doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test"
      ],
      "rationale": "Denetim kayıtlarının gerekli alanları (tür, zaman, yer, kaynak, sonuç, kimlik) içerip içermediği, olaylar tetiklenerek ve kayıtlar incelenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman damplarının UTC cinsinden ve doğru ayrıntı düzeyinde kaydedilip kaydedilmediği, sistem çalıştırılarak ve kayıtlar kontrol edilerek doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin saptanıp saptanamadığı ve uyarıların gönderilip gönderilmediği, saldırı senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Parola ve tek kullanımlık kodların ekranda gizlenip gizlenmediği, giriş ekranında girdi vererek ve ekran görüntüsü alarak gözlemlenmelidir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi dolunca yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, işlem akışı çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test"
      ],
      "rationale": "Veri iletiminin şifreli ve bütünlüğü korunarak yapılıp yapılmadığı, ağ trafiği yakalanarak ve şifreleme protokolleri kontrol edilerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz veya zararlı girdilerin reddedilip reddedilmediği, çeşitli girdi senaryoları uygulayarak ve sistem tepkisi gözlemlenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya genel bilgi verip vermediği ve ayrıntılı logların yetkili personele gösterilip gösterilmediği, hata senaryoları tetiklenerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum süresi uzatılmaması, uyarı gösterilmesi, taslak kaydı ve veri kaybı olmadan devam etme akışının, sistem çalıştırılarak ve süreler beklenerek test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test"
      ],
      "rationale": "CAPTCHA kullanılmaması, bot eşiği aşılınca etkileşimsiz kanıt istenmesi ve istisna sorgu gösterilmesinin, bot simülasyonu ve kullanıcı akışı çalıştırılarak test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi, belirsiz durumda bekleme ve sorgulama akışının, KÖA simülasyonu ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı veya eksik alanlı e-Devlet belirtecinde oturumun sınırlı kipte açılması ve kişisel verilerin gizlenmesi, farklı belirteç senaryoları ile test edilmelidir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca şirket temsilcilerine uygulanması, bildirim gönderilmesi ve ele geçirme kanıtında zorunlu değişikliğin, hesap senaryoları ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilmesi, eski/ileri adımların reddedilmesi ve tek kullanımlık olmasının, zaman senkronizasyonu ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiği aşılınca doğrulayıcının devre dışı bırakılması, hesap kurtarma ile yeniden bağlanma ve sayaç sıfırlamanın, başarısız giriş senaryoları ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 ve AAL3 oturumlarında hareketsizlik sonrası farklı yeniden kimlik doğrulama akışlarının ve oturum sırrı silinmesinin, oturum senaryoları ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması, kullanıcıya bildirim ve SIEM'e olay iletiminin, çoklu oturum senaryoları ile test edilmesi gerekir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, içerik imzası ve boyut/sayı sınırlarının denetlenmesi, ret nedeninin bildirilmesi, farklı dosya yükleme senaryoları ile test edilmelidir."
    }
  ]
