    {
      "requirement_id": "KDH-036",
      "methods": [
        "Test"
      ],
      "rationale": "The recovery mechanisms (recovery codes, bound authenticator, identity proofing) are functional behaviors that can be verified by simulating account recovery scenarios."
    },
    {
      "requirement_id": "KDH-037",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of an authenticator after 50 consecutive failures is a functional behavior that can be verified by simulating 50 failed attempts and then attempting a correct login."
    },
    {
      "requirement_id": "KDH-038",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of multiple authenticators involved in consecutive failures is a functional behavior that can be verified by simulating failures across multiple factors and checking their status."
    },
    {
      "requirement_id": "KDH-039",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to re-bind a disabled authenticator before use is a functional behavior that can be verified by attempting to use a disabled authenticator and then re-binding it."
    },
    {
      "requirement_id": "KDH-040",
      "methods": [
        "Test"
      ],
      "rationale": "The handling of e-Devlet responses that do not meet security levels is a functional behavior that can be verified by simulating such responses and observing the system's reaction."
    },
    {
      "requirement_id": "KDH-041",
      "methods": [
        "Test"
      ],
      "rationale": "The session AAL handling is a functional behavior that can be verified by creating a session at a specific AAL and checking if it is treated at a higher AAL."
    },
    {
      "requirement_id": "KDH-042",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of fallback to insecure transport is a functional behavior that can be verified by attempting to downgrade the connection from HTTPS to HTTP after authentication."
